function linParse(text){
  var pts=[];
  var lines=String(text).split('\n');
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln) continue;
    var parts=ln.split(/[,\t]+/).map(function(x){ return Number(x.trim()); });
    if(parts.length<2||isNaN(parts[0])||isNaN(parts[1]))
      return {value:null, error:'第 '+(i+1)+' 行格式错误（需 x,y）'};
    pts.push([parts[0], parts[1]]);
  }
  return {value:pts, error:null};
}
function linFit(pts){
  var n=pts.length;
  if(n<2) return {value:null, error:'至少需要 2 个点'};
  var sx=0, sy=0, sxx=0, sxy=0, syy=0;
  for(var i=0;i<n;i++){
    var x=pts[i][0], y=pts[i][1];
    sx+=x; sy+=y; sxx+=x*x; sxy+=x*y; syy+=y*y;
  }
  var den=n*sxx-sx*sx;
  if(den===0) return {value:null, error:'x 全部相同，无法拟合'};
  var slope=(n*sxy-sx*sy)/den;
  var intercept=(sy-slope*sx)/n;
  var meanY=sy/n, ssTot=0, ssRes=0;
  for(var j=0;j<n;j++){
    var pred=slope*pts[j][0]+intercept;
    ssTot+=(pts[j][1]-meanY)*(pts[j][1]-meanY);
    ssRes+=(pts[j][1]-pred)*(pts[j][1]-pred);
  }
  var r2 = ssTot===0 ? 1 : 1-ssRes/ssTot;
  var covDen=Math.sqrt((n*sxx-sx*sx)*(n*syy-sy*sy));
  var r = covDen===0 ? 0 : (n*sxy-sx*sy)/covDen;
  return {value:{slope:slope, intercept:intercept, r2:r2, r:r, n:n}, error:null};
}
function linPredict(model, x){ return model.slope*x+model.intercept; }
function linResiduals(model, pts){
  return pts.map(function(p){ return p[1]-linPredict(model, p[0]); });
}
function linRmse(model, pts){
  var res=linResiduals(model, pts);
  var s=0;
  for(var i=0;i<res.length;i++) s+=res[i]*res[i];
  return Math.sqrt(s/res.length);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { linParse:linParse, linFit:linFit, linPredict:linPredict, linResiduals:linResiduals, linRmse:linRmse };
}
if (typeof window !== 'undefined') {
  window.LinearForgePure = { linParse:linParse, linFit:linFit, linPredict:linPredict, linResiduals:linResiduals, linRmse:linRmse };
}
